 930		This formalization-only auxiliary isolates the contraction applied at each
 931		palindromic insertion in \cite[Fact~4.34]{Natarajan2018NEEXP}. If the multipliers $S_z^x$
 932		satisfy
 933		\[
 934			\sum_{z:\,\operatorname{eval}_x(z)=a}(S_z^x)^\dagger S_z^x\leq\Id
 935		\]
 936		for every $x,a$, then left multiplication by $S_z^x$ does not increase the
 937		operator-family distance after reindexing by $\operatorname{eval}_x$.
 938	\end{lemma}
 939	\begin{proof}
 940		\leanok
 941		\uses{lem:distance-sum-contraction}
 942		Group outcomes by their evaluated value and apply the finite-family
 943		contraction estimate on each fiber.
 944	\end{proof}
 945	
 946	% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:504-505) quantifies
 947	% the pairwise-agreement hypothesis over every pair (x, y_1), including pairs carrying
 948	% probability zero under D, on which no conditional distribution of y_2 is defined; the
 949	% hypothesis is restated here over the pairs of positive marginal probability, the only
 950	% pairs the sampling in the hypothesis can refer to and the only ones the averaged
 951	% conclusion depends on. The NEEXP original (references/neexp-paper/
 952	% 05_quantum_preliminaries.tex:1000-1008, label fact:low-degree-sandwich-on-steroids)
 953	% conditions on a fixed question tuple with the same restriction left implicit.
 954	\begin{lemma}[Pasting two consistent measurements; Fact 4.35 in \cite{Natarajan2018NEEXP}]\label{lem:pasting}
 955		\lean{MIPStarRE.QPBT.pastedMeasurement}
 956		\lean{MIPStarRE.QPBT.exists_pasting_error}
 957		\leanok
 958		\uses{def:consistency, def:bracket, def:povm-conventions}
